fn table_node_id(
    graph: &sift_protocol::CatalogGraph,
    source: &DatabaseObjectSource,
) -> Option<sift_protocol::CatalogObjectId> {
    graph.data.nodes.iter().find_map(|node| {
        if node.name != source.object
            || !matches!(
                node.kind,
                sift_protocol::CatalogNodeKind::Table
                    | sift_protocol::CatalogNodeKind::View
                    | sift_protocol::CatalogNodeKind::MaterializedView
                    | sift_protocol::CatalogNodeKind::ForeignTable
                    | sift_protocol::CatalogNodeKind::PartitionedTable
            )
        {
            return None;
        }
        let schema = node.parent_id.as_ref().and_then(|parent| {
            graph
                .data
                .nodes
                .iter()
                .find(|candidate| &candidate.id == parent)
        })?;
        if schema.name != source.schema {
            return None;
        }
        let catalog_matches = source.catalog.as_ref().is_none_or(|catalog| {
            schema
                .parent_id
                .as_ref()
                .and_then(|parent| {
                    graph
                        .data
                        .nodes
                        .iter()
                        .find(|candidate| &candidate.id == parent)
                })
                .is_some_and(|node| &node.name == catalog)
        });
        catalog_matches.then(|| node.id.clone())
    })
}

fn table_detail_nodes<'a>(
    graph: &'a sift_protocol::CatalogGraph,
    table_id: &sift_protocol::CatalogObjectId,
    kind: sift_protocol::CatalogNodeKind,
) -> Vec<&'a sift_protocol::CatalogNode> {
    let mut nodes = graph
        .data
        .nodes
        .iter()
        .filter(|node| node.kind == kind && node.parent_id.as_ref() == Some(table_id))
        .collect::<Vec<_>>();
    nodes.sort_by(|left, right| left.name.cmp(&right.name));
    nodes
}

fn catalog_detail_ddl(
    source: &DatabaseObjectSource,
    node: &sift_protocol::CatalogNode,
) -> Option<String> {
    let qualified_table = format!(
        "{}.{}",
        ddl_quote_identifier(&source.provider_id, &source.schema),
        ddl_quote_identifier(&source.provider_id, &source.object)
    );
    match &node.details {
        sift_protocol::CatalogNodeDetails::Index { index } => {
            let columns = index
                .columns
                .iter()
                .map(|column| {
                    if column
                        .chars()
                        .all(|character| character.is_alphanumeric() || character == '_')
                    {
                        ddl_quote_identifier(&source.provider_id, column)
                    } else {
                        column.clone()
                    }
                })
                .collect::<Vec<_>>()
                .join(", ");
            let mut ddl = format!(
                "-- Catalog-derived index DDL preview\nCREATE {}INDEX {} ON {} ({})",
                if index.unique { "UNIQUE " } else { "" },
                ddl_quote_identifier(&source.provider_id, &index.name),
                qualified_table,
                columns
            );
            if let Some(predicate) = &index.partial_predicate {
                ddl.push_str(" WHERE ");
                ddl.push_str(predicate);
            }
            ddl.push(';');
            Some(ddl)
        }
        sift_protocol::CatalogNodeDetails::Constraint { constraint } => Some(
            constraint
                .definition
                .as_ref()
                .map(|definition| {
                    format!(
                        "-- Catalog relation definition\nALTER TABLE {} ADD CONSTRAINT {} {};",
                        qualified_table,
                        ddl_quote_identifier(&source.provider_id, &constraint.name),
                        definition.trim().trim_end_matches(';')
                    )
                })
                .unwrap_or_else(|| {
                    format!(
                        "-- DDL definition is unavailable for relation {}.",
                        constraint.name
                    )
                }),
        ),
        sift_protocol::CatalogNodeDetails::Trigger { trigger } => {
            Some(trigger.definition.clone().unwrap_or_else(|| {
                format!(
                    "-- DDL definition is unavailable for trigger {}.",
                    trigger.name
                )
            }))
        }
        _ => None,
    }
}

fn catalog_columns_ddl(
    source: &DatabaseObjectSource,
    graph: &sift_protocol::CatalogGraph,
    table_id: &sift_protocol::CatalogObjectId,
    columns_only: bool,
) -> String {
    let qualified_relation = format!(
        "{}.{}",
        ddl_quote_identifier(&source.provider_id, &source.schema),
        ddl_quote_identifier(&source.provider_id, &source.object)
    );
    let columns = table_columns(graph, table_id)
        .into_iter()
        .filter_map(|node| {
            let sift_protocol::CatalogNodeDetails::Column { column } = &node.details else {
                return None;
            };
            Some(format!(
                "    {} {}{}",
                ddl_quote_identifier(&source.provider_id, &node.name),
                type_ref_label(&column.type_ref),
                if column.nullable == sift_protocol::Nullability::NotNullable {
                    " NOT NULL"
                } else {
                    ""
                }
            ))
        })
        .collect::<Vec<_>>();
    if matches!(
        source.object_kind,
        sift_protocol::ObjectKind::Table
            | sift_protocol::ObjectKind::ForeignTable
            | sift_protocol::ObjectKind::PartitionedTable
    ) {
        let scope = if columns_only {
            "-- Columns only; indexes, constraints, triggers, storage, and grants are omitted."
        } else {
            "-- Base relation definition; engine-specific storage and grants may be omitted."
        };
        format!(
            "-- Catalog-derived relation DDL preview\n{scope}\nCREATE TABLE {qualified_relation} (\n{}\n);",
            columns.join(",\n")
        )
    } else {
        format!(
            "-- Catalog-derived column metadata for {qualified_relation}\n-- Exact relation DDL is unavailable in this UI foundation.\n{}",
            columns.join("\n")
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum TableDefinitionSection {
    Columns,
    Indexes,
    Relations,
    Triggers,
    Dependencies,
}

impl TableDefinitionSection {
    const ALL: [Self; 5] = [
        Self::Columns,
        Self::Indexes,
        Self::Relations,
        Self::Triggers,
        Self::Dependencies,
    ];

    fn label(self) -> &'static str {
        match self {
            Self::Columns => "Columns",
            Self::Indexes => "Indexes",
            Self::Relations => "Relations",
            Self::Triggers => "Triggers",
            Self::Dependencies => "Dependencies",
        }
    }
}

fn table_columns<'a>(
    graph: &'a sift_protocol::CatalogGraph,
    table_id: &sift_protocol::CatalogObjectId,
) -> Vec<&'a sift_protocol::CatalogNode> {
    let mut columns = graph
        .data
        .nodes
        .iter()
        .filter(|node| {
            node.kind == sift_protocol::CatalogNodeKind::Column
                && node.parent_id.as_ref() == Some(table_id)
        })
        .collect::<Vec<_>>();
    columns.sort_by_key(|node| node.ordinal.unwrap_or(u32::MAX));
    columns
}

/// Schema objects are grouped into these buckets inside each schema node.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum ObjectGroupKind {
    Tables,
    Views,
    Functions,
    Sequences,
    Other,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WorkspaceSurface {
    Editor,
    Connections,
    Inspector,
    Results,
    Problems,
}

#[derive(Debug, Clone)]
struct ConnectionTreeItem {
    depth: usize,
    action: ConnectionTreeAction,
}

#[derive(Debug, Clone)]
enum ConnectionTreeAction {
    Tenant(i64),
    Connection(ConnectionNavEntry),
    Catalog {
        profile_id: i64,
        catalog: String,
    },
    Schema {
        profile_id: i64,
        catalog: String,
        schema: String,
    },
    Group {
        profile_id: i64,
        catalog: String,
        schema: String,
        group: ObjectGroupKind,
    },
    Object(DatabaseObjectTarget),
    Room(i64),
    Workspace(WorkspaceNavEntry),
    Document(DocumentNavEntry),
}

impl ObjectGroupKind {
    const CANONICAL: [Self; 5] = [
        Self::Tables,
        Self::Views,
        Self::Functions,
        Self::Sequences,
        Self::Other,
    ];

    fn label(self) -> &'static str {
        match self {
            Self::Tables => "Tables",
            Self::Views => "Views",
            Self::Functions => "Functions",
            Self::Sequences => "Sequences",
            Self::Other => "Other",
        }
    }

    fn icon(self) -> IconName {
        match self {
            Self::Tables => IconName::Table,
            Self::Views => IconName::View,
            Self::Functions => IconName::Function,
            Self::Sequences => IconName::Sequence,
            Self::Other => IconName::Folder,
        }
    }

    fn from_object_kind(kind: sift_protocol::ObjectKind) -> Self {
        use sift_protocol::ObjectKind;
        match kind {
            ObjectKind::Table | ObjectKind::ForeignTable | ObjectKind::PartitionedTable => {
                Self::Tables
            }
            ObjectKind::View | ObjectKind::MaterializedView => Self::Views,
            ObjectKind::ScalarFunction
            | ObjectKind::TableValuedFunction
            | ObjectKind::Procedure => Self::Functions,
            ObjectKind::Sequence => Self::Sequences,
            ObjectKind::Trigger
            | ObjectKind::Synonym
            | ObjectKind::Type
            | ObjectKind::Extension => Self::Other,
        }
    }
}

/// Left padding for a tree row at the given depth. Levels step by a constant
/// 14px so chevrons, icons, and labels each form one aligned column.
fn tree_indent(level: usize) -> Pixels {
    px(6. + 14. * level as f32)
}

/// Fixed-width slot holding a row's disclosure chevron. Leaf rows render an
/// empty slot instead so their icons stay aligned with sibling containers.
fn tree_chevron_slot(open: bool, color: Hsla) -> Div {
    div()
        .flex_none()
        .w(px(14.))
        .flex()
        .items_center()
        .child(icon(
            if open {
                IconName::ChevronDown
            } else {
                IconName::ChevronRight
            },
            color,
            11.,
        ))
}

fn tree_spacer_slot() -> Div {
    div().flex_none().w(px(14.))
}

/// Full-colour vendor artwork for a connection's engine, when we carry it.
fn provider_logo_asset(provider_id: &sift_protocol::ProviderId) -> Option<&'static str> {
    match provider_id.as_str() {
        "sift/postgres" => Some("databases/postgres.svg"),
        "sift/sql-server" => Some("databases/sql-server.svg"),
        _ => None,
    }
}

/// Compact engine name shown next to connection names in the tree.
fn provider_display_name(provider_id: &sift_protocol::ProviderId) -> Option<&'static str> {
    match provider_id.as_str() {
        "sift/postgres" => Some("PostgreSQL"),
        "sift/sql-server" => Some("SQL Server"),
        _ => None,
    }
}

fn schema_object_kind_icon(kind: sift_protocol::ObjectKind) -> IconName {
    use sift_protocol::ObjectKind;
    match kind {
        ObjectKind::Table | ObjectKind::ForeignTable | ObjectKind::PartitionedTable => {
            IconName::Table
        }
        ObjectKind::View | ObjectKind::MaterializedView => IconName::View,
        ObjectKind::ScalarFunction | ObjectKind::TableValuedFunction | ObjectKind::Procedure => {
            IconName::Function
        }
        ObjectKind::Sequence => IconName::Sequence,
        ObjectKind::Trigger | ObjectKind::Synonym | ObjectKind::Type | ObjectKind::Extension => {
            IconName::Fallback
        }
    }
}

