/// A pane tab being dragged. `pane_id` distinguishes a same-pane reorder from
/// a cross-pane move; `item_id` is stable across the drag.
#[derive(Debug, Clone, PartialEq, Eq)]
struct TabDrag {
    pane_id: u64,
    item_id: u64,
    index: usize,
    title: SharedString,
    selected: bool,
    dirty: bool,
}

impl gpui::Render for TabDrag {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        PaneTab::new("dragged-tab")
            .selected(self.selected)
            .dirty(self.dirty)
            .child(div().min_w_0().px_2().truncate().child(self.title.clone()))
            .render(window, cx)
    }
}

