/// A pane owns its ordered items and focus handle. The workspace owns panes;
/// items never reach sideways into sibling panes.
pub struct Pane {
    id: u64,
    items: Vec<ItemPresentation>,
    active_item: usize,
    backward_items: Vec<u64>,
    forward_items: Vec<u64>,
    focus_handle: FocusHandle,
    tab_scroll_handle: ScrollHandle,
    /// Live editor per SQL or configuration item. Editor contents are not
    /// persisted in the local layout; their owning service rehydrates them.
    editors: HashMap<u64, Entity<QueryEditor>>,
    /// Text at the last clean point for each editor. Comparing content rather
    /// than latching a boolean means undoing back to the clean text is clean.
    clean_documents: HashMap<u64, String>,
    /// Live editor subscriptions, keyed by item. Stored (not detached) so a
    /// tab moved to another pane unsubscribes instead of double-reporting.
    editor_subscriptions: HashMap<u64, Subscription>,
    /// The Data/Messages/Explain/History surface owned by each query item.
    results: HashMap<u64, Entity<ResultsView>>,
    /// Live results subscriptions, keyed by item, held for the same reason as
    /// `editor_subscriptions`.
    result_subscriptions: HashMap<u64, Subscription>,
    database_item_states: HashMap<u64, DatabaseItemState>,
    database_item_views: HashMap<u64, DatabaseItemView>,
    database_query_texts: HashMap<u64, String>,
    database_ddl_texts: HashMap<u64, String>,
    /// Transient wrapper sizes while dragging. Keeping these on the pane avoids
    /// invalidating and repainting the result grid for every pointer event.
    live_result_extents: HashMap<u64, f32>,
    /// Mouse-move events may outpace display refresh. One pane invalidation per
    /// frame keeps result resizing responsive without redundant layout passes.
    result_resize_frame_pending: bool,
    /// Shape a dragged tab would take if released over this pane body.
    /// Tab-bar hover styling is ephemeral GPUI `drag_over` state instead.
    tab_drop_target: Option<PaneDropTarget>,
    /// Last body bounds associated with the preview. The workspace-level drag
    /// listener clears the active hint in O(1) when the pointer leaves.
    tab_drag_preview_bounds: Option<Bounds<Pixels>>,
    /// The workspace-edge target supersedes this pane's local target. Keeping
    /// the local state warm makes leaving the outer edge transition instantly.
    suppress_tab_drag_preview: bool,
    /// Last tab-strip bounds observed during this drag. The workspace checks
    /// these before resolving outer-edge targets so tab insertion wins even
    /// when both nested drag listeners receive the same pointer move.
    tab_bar_drag_bounds: Option<Bounds<Pixels>>,
    /// Dirty-close confirmation belongs to its tab and is rendered inline.
    pending_close_item: Option<u64>,
    /// The live result entity is mounted in the workspace modal while this is
    /// set, so it never renders twice with one scroll handle.
    expanded_result_item: Option<u64>,
}

impl Pane {
    fn from_presentation(
        pane: PanePresentation,
        vim_mode_default: bool,
        cx: &mut Context<Self>,
    ) -> Self {
        let PanePresentation {
            id,
            mut items,
            active_item,
        } = pane;
        let mut editors = HashMap::new();
        let mut clean_documents = HashMap::new();
        let mut editor_subscriptions = HashMap::new();
        let mut results = HashMap::new();
        let mut result_subscriptions = HashMap::new();
        let mut database_item_states = HashMap::new();
        let mut database_item_views = HashMap::new();
        for item in items
            .iter_mut()
            .filter(|item| ItemRegistry::definition(&item.kind).runtime.is_editor())
        {
            // Editor text is rehydrated independently of presentation state.
            // A persisted dirty bit without its document would create a false
            // close warning for an unchanged, empty editor.
            item.dirty = false;
            let id = item.id;
            let restored_text = match item.source.as_ref() {
                Some(ItemSource::DatabaseObject(source)) => {
                    table_preview_sql(&source.provider_id, &source.schema, &source.object)
                }
                Some(ItemSource::RoomDocument(_)) => String::new(),
                None => String::new(),
            };
            let document = QueryDocument::with_random_peer(&restored_text);
            let language = match item.kind {
                ItemKind::Configuration if item.title.ends_with(".json") => EditorLanguage::Json,
                ItemKind::Configuration => EditorLanguage::Toml,
                ItemKind::Problems => EditorLanguage::PlainText,
                ItemKind::Query | ItemKind::Schema | ItemKind::Welcome => EditorLanguage::Sql,
            };
            let keymap = if vim_mode_default {
                EditorKeymap::Vim
            } else {
                EditorKeymap::Standard
            };
            let read_only = item.kind == ItemKind::Problems;
            let editor = cx.new(|cx| {
                let editor = QueryEditor::new(document, cx)
                    .with_language(language)
                    .with_keymap(keymap);
                let editor = if item.title == "keymaps.json" {
                    editor.with_json_schema(JsonSchema::keymaps(
                        CommandRegistry::definitions()
                            .iter()
                            .map(|definition| definition.id.as_str().to_owned()),
                    ))
                } else {
                    editor
                };
                if read_only {
                    editor.read_only()
                } else {
                    editor
                }
            });
            editor_subscriptions.insert(
                id,
                cx.subscribe(&editor, move |pane, _, event, cx| {
                    pane.on_editor_event(id, event, cx);
                }),
            );
            editors.insert(id, editor);
            clean_documents.insert(id, restored_text);
            if item.kind == ItemKind::Query {
                let view = cx.new(ResultsView::new);
                // A restored tab shows what it last produced as a reference.
                // The rows themselves were never written to disk.
                if let Some(reference) = item.last_result.clone() {
                    view.update(cx, |view, cx| view.restore_reference(reference, cx));
                }
                result_subscriptions.insert(
                    id,
                    cx.subscribe(&view, move |pane, _, event, cx| {
                        pane.on_results_event(id, event, cx);
                    }),
                );
                results.insert(id, view);
            }
            if matches!(item.source, Some(ItemSource::DatabaseObject(_))) {
                database_item_states.insert(id, DatabaseItemState::Offline);
                database_item_views.insert(id, DatabaseItemView::Query);
            }
        }
        Self {
            id,
            items,
            active_item,
            backward_items: Vec::new(),
            forward_items: Vec::new(),
            focus_handle: cx.focus_handle(),
            tab_scroll_handle: ScrollHandle::new(),
            editors,
            clean_documents,
            editor_subscriptions,
            results,
            result_subscriptions,
            database_item_states,
            database_item_views,
            database_query_texts: HashMap::new(),
            database_ddl_texts: HashMap::new(),
            live_result_extents: HashMap::new(),
            result_resize_frame_pending: false,
            tab_drop_target: None,
            tab_drag_preview_bounds: None,
            suppress_tab_drag_preview: false,
            tab_bar_drag_bounds: None,
            pending_close_item: None,
            expanded_result_item: None,
        }
    }

    /// Adopt a results surface for `item_id`, subscribing to its intents.
    fn attach_results(&mut self, item_id: u64, view: Entity<ResultsView>, cx: &mut Context<Self>) {
        self.result_subscriptions.insert(
            item_id,
            cx.subscribe(&view, move |pane, _, event, cx| {
                pane.on_results_event(item_id, event, cx);
            }),
        );
        self.results.insert(item_id, view);
    }

    fn targeted_query_sql(&self, item_id: u64, cx: &App) -> String {
        self.editors
            .get(&item_id)
            .map(|editor| targeted_query_text(editor.read(cx).document()))
            .unwrap_or_default()
    }

    fn on_results_event(&mut self, item_id: u64, event: &ResultsEvent, cx: &mut Context<Self>) {
        match event {
            ResultsEvent::LoadNextWindowRequested => {
                cx.emit(PaneEvent::LoadNextRowWindowRequested { item_id })
            }
            ResultsEvent::OpenDataModalRequested => {
                cx.emit(PaneEvent::OpenDataResultsRequested { item_id })
            }
            ResultsEvent::EditSelectedCellRequested => {
                cx.emit(PaneEvent::EditResultCellRequested { item_id })
            }
            ResultsEvent::ExplainRequested { analyze } => {
                let sql = self.targeted_query_sql(item_id, cx);
                cx.emit(PaneEvent::ExplainRequested {
                    item_id,
                    sql,
                    analyze: *analyze,
                });
            }
            ResultsEvent::CapturePlanRequested => {
                let sql = self.targeted_query_sql(item_id, cx);
                cx.emit(PaneEvent::CapturePlanRequested { item_id, sql });
            }
            ResultsEvent::OpenPlanCapturesRequested => {
                cx.emit(PaneEvent::OpenPlanCapturesRequested {
                    item_id,
                    sql: self.targeted_query_sql(item_id, cx),
                });
            }
            ResultsEvent::HistoryRequested { cursor } => cx.emit(PaneEvent::HistoryRequested {
                item_id,
                cursor: cursor.clone(),
            }),
            ResultsEvent::RerunHistory { sql } => cx.emit(PaneEvent::RerunHistoryRequested {
                item_id,
                sql: sql.clone(),
            }),
        }
    }

    fn on_editor_event(&mut self, item_id: u64, event: &EditorEvent, cx: &mut Context<Self>) {
        match event {
            EditorEvent::DocumentChanged { update } => {
                let dirty = self.editors.get(&item_id).is_some_and(|editor| {
                    self.clean_documents
                        .get(&item_id)
                        .is_none_or(|clean| editor.read(cx).document().text() != clean)
                });
                cx.emit(PaneEvent::EditorStateChanged {
                    item_id,
                    dirty: Some(dirty),
                });
                cx.emit(PaneEvent::RoomUpdateRequested {
                    item_id,
                    update: update.clone(),
                });
            }
            EditorEvent::CursorChanged | EditorEvent::VimStateChanged => {
                cx.emit(PaneEvent::EditorStateChanged {
                    item_id,
                    dirty: None,
                })
            }
            EditorEvent::OpenCommandPalette => cx.emit(PaneEvent::OpenCommandPaletteRequested),
            EditorEvent::Execute { sql } => {
                // Show the pending state immediately, then ask the workspace to
                // dispatch the run. The workspace owns the executor channel.
                if let Some(result) = self.results.get(&item_id) {
                    result.update(cx, |result, cx| result.set_pending(cx));
                }
                cx.emit(PaneEvent::ExecuteRequested {
                    item_id,
                    sql: sql.clone(),
                });
            }
            EditorEvent::SemanticRequest { revision, request } => {
                cx.emit(PaneEvent::SemanticRequested {
                    item_id,
                    revision: *revision,
                    request: request.clone(),
                });
            }
        }
    }

    /// Record the reference to a finished run on its tab, or clear it when a
    /// new run starts. Returns whether this pane owns the item.
    fn set_last_result(&mut self, item_id: u64, reference: Option<ResultReference>) -> bool {
        match self.items.iter_mut().find(|item| item.id == item_id) {
            Some(item) => {
                item.last_result = reference;
                true
            }
            None => false,
        }
    }

    /// Apply an execution outcome to the query item's results surface.
    /// Returns whether this pane owns the item.
    fn set_result(&mut self, item_id: u64, state: ResultState, cx: &mut Context<Self>) -> bool {
        match self.results.get(&item_id) {
            Some(result) => {
                result.update(cx, |result, cx| result.set_state(state, cx));
                true
            }
            None => false,
        }
    }

    fn set_explain_result(
        &mut self,
        item_id: u64,
        response: Result<Box<sift_protocol::ExplainResponse>, String>,
        cx: &mut Context<Self>,
    ) -> bool {
        match self.results.get(&item_id) {
            Some(result) => {
                result.update(cx, |result, cx| result.set_explain_result(response, cx));
                true
            }
            None => false,
        }
    }

    fn begin_result_stream(&mut self, item_id: u64, cx: &mut Context<Self>) -> bool {
        match self.results.get(&item_id) {
            Some(result) => {
                result.update(cx, |result, cx| result.begin_stream(cx));
                true
            }
            None => false,
        }
    }

    fn apply_result_page(
        &mut self,
        item_id: u64,
        page: sift_protocol::Page,
        cx: &mut Context<Self>,
    ) -> Option<(StreamProgress, ResultState)> {
        let result = self.results.get(&item_id)?;
        let progress = result.update(cx, |result, cx| result.apply_stream_page(page, cx));
        Some((progress, result.read(cx).state().clone()))
    }

    /// Discard the retained window so the held page can be consumed.
    fn advance_result_window(&mut self, item_id: u64, cx: &mut Context<Self>) -> bool {
        match self.results.get(&item_id) {
            Some(result) => result.update(cx, |result, cx| result.advance_window(cx)),
            None => false,
        }
    }

    fn snapshot(&self) -> PanePresentation {
        let items = self
            .items
            .iter()
            .filter(|item| !matches!(item.kind, ItemKind::Configuration | ItemKind::Problems))
            .cloned()
            .collect::<Vec<_>>();
        let active_id = self.active_item().map(|item| item.id);
        let active_item = active_id
            .and_then(|active| items.iter().position(|item| item.id == active))
            .unwrap_or_else(|| items.len().saturating_sub(1));
        PanePresentation {
            id: self.id,
            items,
            active_item,
        }
    }

    fn active_item(&self) -> Option<&ItemPresentation> {
        self.items.get(self.active_item)
    }

    fn active_item_mut(&mut self) -> Option<&mut ItemPresentation> {
        self.items.get_mut(self.active_item)
    }

    /// The focus handle that should receive keyboard input for this pane: the
    /// active query item's editor when there is one, else the pane itself. This
    /// keeps the `SiftEditor` key context active so editing keys route.
    fn active_focus_handle(&self, cx: &App) -> FocusHandle {
        self.active_item()
            .filter(|item| ItemRegistry::definition(&item.kind).runtime.is_editor())
            .and_then(|item| self.editors.get(&item.id))
            .map(|editor| editor.focus_handle(cx))
            .unwrap_or_else(|| self.focus_handle.clone())
    }

    fn active_cursor_position(&self, cx: &App) -> Option<(usize, usize)> {
        let item = self.active_item()?;
        self.editors
            .get(&item.id)
            .map(|editor| editor.read(cx).cursor_position())
    }

    fn active_editor_mode(&self, cx: &App) -> Option<(EditorKeymap, VimMode, String)> {
        let item = self.active_item()?;
        self.editors.get(&item.id).map(|editor| {
            let editor = editor.read(cx);
            (
                editor.keymap(),
                editor.vim_mode(),
                editor.vim_entered().to_owned(),
            )
        })
    }

    fn contains_item(&self, item_id: u64) -> bool {
        self.items.iter().any(|item| item.id == item_id)
    }

    fn editor(&self, item_id: u64) -> Option<Entity<QueryEditor>> {
        self.editors.get(&item_id).cloned()
    }

    fn active_results(&self) -> Option<Entity<ResultsView>> {
        self.active_item()
            .and_then(|item| self.results.get(&item.id))
            .cloned()
    }

    fn database_source(&self, item_id: u64) -> Option<DatabaseObjectSource> {
        self.items
            .iter()
            .find(|item| item.id == item_id)
            .and_then(|item| item.source.as_ref())
            .and_then(|source| match source {
                ItemSource::DatabaseObject(source) => Some(source.clone()),
                ItemSource::RoomDocument(_) => None,
            })
    }

    fn room_document_source(&self, item_id: u64) -> Option<RoomDocumentSource> {
        self.items
            .iter()
            .find(|item| item.id == item_id)
            .and_then(|item| item.source.as_ref())
            .and_then(|source| match source {
                ItemSource::RoomDocument(source) => Some(source.clone()),
                ItemSource::DatabaseObject(_) => None,
            })
    }

    fn set_database_item_state(&mut self, item_id: u64, state: DatabaseItemState) {
        if self.database_source(item_id).is_some() {
            self.database_item_states.insert(item_id, state);
        }
    }

    fn set_all_database_item_states(&mut self, state: DatabaseItemState) {
        let ids = self
            .items
            .iter()
            .filter(|item| matches!(item.source, Some(ItemSource::DatabaseObject(_))))
            .map(|item| item.id)
            .collect::<Vec<_>>();
        for item_id in ids {
            self.database_item_states.insert(item_id, state.clone());
        }
    }

    fn show_database_item_view(
        &mut self,
        item_id: u64,
        view: DatabaseItemView,
        generated_ddl: Option<String>,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.database_source(item_id).is_none() {
            return false;
        }
        let Some(editor) = self.editors.get(&item_id).cloned() else {
            return false;
        };
        let current_view = self
            .database_item_views
            .get(&item_id)
            .copied()
            .unwrap_or(DatabaseItemView::Query);
        let current_text = editor.read(cx).document().text().to_owned();
        match current_view {
            DatabaseItemView::Query => {
                self.database_query_texts.insert(item_id, current_text);
            }
            DatabaseItemView::Ddl => {
                self.database_ddl_texts.insert(item_id, current_text);
            }
        }
        if let Some(ddl) = generated_ddl {
            self.database_ddl_texts.insert(item_id, ddl);
        }
        let replacement = match view {
            DatabaseItemView::Query => self.database_query_texts.get(&item_id),
            DatabaseItemView::Ddl => self.database_ddl_texts.get(&item_id),
        }
        .cloned()
        .unwrap_or_default();
        editor.update(cx, |editor, cx| {
            editor.replace_text_from_owner(&replacement, cx)
        });
        self.database_item_views.insert(item_id, view);
        cx.notify();
        true
    }

    fn mark_database_item_refreshed(&mut self, item_id: u64) {
        let refreshed_at = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .ok()
            .and_then(|duration| u64::try_from(duration.as_millis()).ok());
        let Some(item) = self.items.iter_mut().find(|item| item.id == item_id) else {
            return;
        };
        let Some(ItemSource::DatabaseObject(source)) = item.source.as_mut() else {
            return;
        };
        source.last_refreshed_at_ms = refreshed_at;
        self.database_item_states
            .insert(item_id, DatabaseItemState::Live);
    }

    fn can_navigate_backward(&self) -> bool {
        self.backward_items
            .iter()
            .any(|id| self.items.iter().any(|item| item.id == *id))
    }

    fn can_navigate_forward(&self) -> bool {
        self.forward_items
            .iter()
            .any(|id| self.items.iter().any(|item| item.id == *id))
    }

    fn activate_item(&mut self, index: usize, record_history: bool) {
        if index >= self.items.len() || index == self.active_item {
            return;
        }
        if record_history {
            if let Some(current) = self.active_item().map(|item| item.id) {
                self.backward_items.push(current);
            }
            self.forward_items.clear();
        }
        self.active_item = index;
        self.tab_scroll_handle.scroll_to_item(index);
    }

    fn navigate_backward(&mut self) {
        while let Some(id) = self.backward_items.pop() {
            let Some(index) = self.items.iter().position(|item| item.id == id) else {
                continue;
            };
            if let Some(current) = self.active_item().map(|item| item.id) {
                self.forward_items.push(current);
            }
            self.active_item = index;
            self.tab_scroll_handle.scroll_to_item(index);
            break;
        }
    }

    fn navigate_forward(&mut self) {
        while let Some(id) = self.forward_items.pop() {
            let Some(index) = self.items.iter().position(|item| item.id == id) else {
                continue;
            };
            if let Some(current) = self.active_item().map(|item| item.id) {
                self.backward_items.push(current);
            }
            self.active_item = index;
            self.tab_scroll_handle.scroll_to_item(index);
            break;
        }
    }

    fn forget_item(&mut self, item_id: u64) {
        self.backward_items.retain(|id| *id != item_id);
        self.forward_items.retain(|id| *id != item_id);
        self.clean_documents.remove(&item_id);
        self.editor_subscriptions.remove(&item_id);
        self.live_result_extents.remove(&item_id);
        self.database_item_views.remove(&item_id);
        self.database_query_texts.remove(&item_id);
        self.database_ddl_texts.remove(&item_id);
        if self.pending_close_item == Some(item_id) {
            self.pending_close_item = None;
        }
    }

    fn replace_new_pane_placeholder(&mut self) -> bool {
        let Some(placeholder_id) = self.items.first().and_then(|item| {
            (self.items.len() == 1
                && item.kind == ItemKind::Welcome
                && item.title == "New pane"
                && !item.dirty)
                .then_some(item.id)
        }) else {
            return false;
        };

        self.items.clear();
        self.active_item = 0;
        self.editors.remove(&placeholder_id);
        self.results.remove(&placeholder_id);
        self.forget_item(placeholder_id);
        true
    }

    fn mark_clean(&mut self, item_id: u64, cx: &App) {
        if let Some(editor) = self.editors.get(&item_id) {
            self.clean_documents
                .insert(item_id, editor.read(cx).document().text().to_owned());
        }
        if let Some(item) = self.items.iter_mut().find(|item| item.id == item_id) {
            item.dirty = false;
        }
    }

    fn open_configuration(
        &mut self,
        item: ItemPresentation,
        editor: Entity<QueryEditor>,
        cx: &mut Context<Self>,
    ) {
        let item_id = item.id;
        if let Some(index) = self
            .items
            .iter()
            .position(|candidate| candidate.id == item_id)
        {
            self.items[index] = item;
            self.activate_item(index, true);
        } else {
            if !self.replace_new_pane_placeholder() {
                if let Some(current) = self.active_item().map(|item| item.id) {
                    self.backward_items.push(current);
                    self.forward_items.clear();
                }
            }
            self.items.push(item);
            self.active_item = self.items.len() - 1;
        }
        self.editor_subscriptions.insert(
            item_id,
            cx.subscribe(&editor, move |pane, _, event, cx| {
                pane.on_editor_event(item_id, event, cx);
            }),
        );
        self.clean_documents
            .insert(item_id, editor.read(cx).document().text().to_owned());
        self.editors.insert(item_id, editor);
        self.results.remove(&item_id);
        self.database_item_states.remove(&item_id);
        self.pending_close_item = None;
        cx.notify();
    }

    fn open_query(
        &mut self,
        item: ItemPresentation,
        editor: Entity<QueryEditor>,
        results: Entity<ResultsView>,
        cx: &mut Context<Self>,
    ) {
        let item_id = item.id;
        if !self.replace_new_pane_placeholder() {
            if let Some(current) = self.active_item().map(|item| item.id) {
                self.backward_items.push(current);
                self.forward_items.clear();
            }
        }
        self.items.push(item);
        self.active_item = self.items.len() - 1;
        self.editor_subscriptions.insert(
            item_id,
            cx.subscribe(&editor, move |pane, _, event, cx| {
                pane.on_editor_event(item_id, event, cx);
            }),
        );
        self.clean_documents
            .insert(item_id, editor.read(cx).document().text().to_owned());
        self.editors.insert(item_id, editor);
        self.attach_results(item_id, results, cx);
        if matches!(
            self.items.last().and_then(|item| item.source.as_ref()),
            Some(ItemSource::DatabaseObject(_))
        ) {
            self.database_item_states
                .insert(item_id, DatabaseItemState::Offline);
            self.database_item_views
                .insert(item_id, DatabaseItemView::Query);
        }
        cx.notify();
    }

    fn resize_results(
        &mut self,
        event: &gpui::DragMoveEvent<ResultResizeDrag>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let drag = *event.drag(cx);
        if !self.results.contains_key(&drag.item_id) {
            return;
        }
        let width: f32 = event.bounds.size.width.into();
        let height: f32 = event.bounds.size.height.into();
        let pointer_x: f32 = (event.event.position.x - event.bounds.left()).into();
        let pointer_y: f32 = (event.event.position.y - event.bounds.top()).into();
        let extent = match drag.placement {
            ResultPlacement::Bottom => (height - pointer_y)
                .max(RESULT_MIN_EXTENT)
                .min((height - EDITOR_MIN_EXTENT).max(RESULT_MIN_EXTENT)),
            ResultPlacement::Right => (width - pointer_x)
                .max(RESULT_MIN_EXTENT)
                .min((width - EDITOR_MIN_EXTENT).max(RESULT_MIN_EXTENT)),
        };
        self.queue_result_resize(drag.item_id, extent, window, cx);
    }

    fn queue_result_resize(
        &mut self,
        item_id: u64,
        extent: f32,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        // Sub-pixel wrapper changes still trigger full layout. Snap them away,
        // and skip pointer events that resolve to the current visible extent.
        let extent = extent.round();
        let current = self.live_result_extents.get(&item_id).copied().or_else(|| {
            self.results
                .get(&item_id)
                .map(|result| result.read(cx).extent())
        });
        if current == Some(extent) {
            return;
        }
        self.live_result_extents.insert(item_id, extent);

        if self.result_resize_frame_pending {
            return;
        }
        self.result_resize_frame_pending = true;
        cx.notify();
        cx.on_next_frame(window, |pane, _, _| {
            pane.result_resize_frame_pending = false;
        });
    }

    fn finish_results_resize(
        &mut self,
        drag: &ResultResizeDrag,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(extent) = self.live_result_extents.remove(&drag.item_id) else {
            return;
        };
        if let Some(results) = self.results.get(&drag.item_id) {
            results.update(cx, |results, cx| results.set_extent(extent, cx));
        }
    }

    /// Drop directly on a tab. Like Zed, targets before the source insert on
    /// their left and targets after the source insert on their right.
    fn tab_bar_drag_hover(
        &mut self,
        event: &gpui::DragMoveEvent<TabDrag>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !event.bounds.contains(&event.event.position) {
            return;
        }
        let had_structural_preview =
            self.tab_drop_target.take().is_some() || self.tab_drag_preview_bounds.take().is_some();
        if self.tab_bar_drag_bounds != Some(event.bounds) {
            self.tab_bar_drag_bounds = Some(event.bounds);
            cx.emit(PaneEvent::TabBarDragEntered);
        }
        if had_structural_preview {
            cx.notify();
        }
    }

    fn finish_tab_bar_drag(
        &mut self,
        index: usize,
        drag: &TabDrag,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.tab_drop_target = None;
        self.tab_drag_preview_bounds = None;
        self.suppress_tab_drag_preview = false;
        self.tab_bar_drag_bounds = None;
        let insertion_index =
            if drag.pane_id == self.id && index > drag.index && index < self.items.len() {
                index + 1
            } else {
                index
            };
        if drag.pane_id == self.id {
            self.move_item(drag.item_id, insertion_index);
        } else {
            cx.emit(PaneEvent::MoveItemRequested {
                item_id: drag.item_id,
                target: PaneDropTarget::Tab(insertion_index),
            });
        }
        cx.emit(PaneEvent::FocusRequested);
        cx.notify();
    }

    /// Track Zed-style pane landing zones. The nearest outer edge creates a
    /// pane in that direction; the broad middle joins the pane.
    fn pane_drag_hover(
        &mut self,
        event: &gpui::DragMoveEvent<TabDrag>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !event.bounds.contains(&event.event.position) {
            return;
        }
        self.tab_bar_drag_bounds = None;
        let relative_x = event.event.position.x - event.bounds.left();
        let relative_y = event.event.position.y - event.bounds.top();
        let width = event.bounds.size.width;
        let height = event.bounds.size.height;
        let edge = width.min(height) * PANE_DROP_TARGET_FRACTION;
        let left = relative_x;
        let right = width - relative_x;
        let top = relative_y;
        let bottom = height - relative_y;
        let nearest = left.min(right).min(top).min(bottom);
        let target = if nearest >= edge {
            PaneDropTarget::Center
        } else if nearest == left {
            PaneDropTarget::Before
        } else if nearest == right {
            PaneDropTarget::After
        } else if nearest == top {
            PaneDropTarget::Above
        } else {
            PaneDropTarget::Below
        };
        let activating = self.tab_drag_preview_bounds.is_none();
        if self.tab_drop_target != Some(target)
            || self.tab_drag_preview_bounds != Some(event.bounds)
        {
            self.tab_drop_target = Some(target);
            self.tab_drag_preview_bounds = Some(event.bounds);
            if activating {
                cx.emit(PaneEvent::DragPreviewActivated);
            }
        }
    }

    /// A dragged tab was released over this pane: reorder locally, or ask the
    /// workspace to move it here from its originating pane.
    fn finish_tab_drag(&mut self, drag: &TabDrag, _: &mut Window, cx: &mut Context<Self>) {
        let target = self
            .tab_drop_target
            .take()
            .unwrap_or(PaneDropTarget::Center);
        self.tab_drag_preview_bounds = None;
        self.suppress_tab_drag_preview = false;
        self.tab_bar_drag_bounds = None;
        let creates_pane = matches!(
            target,
            PaneDropTarget::Above
                | PaneDropTarget::Before
                | PaneDropTarget::After
                | PaneDropTarget::Below
        );
        if drag.pane_id != self.id || creates_pane {
            cx.emit(PaneEvent::MoveItemRequested {
                item_id: drag.item_id,
                target,
            });
        } else if let PaneDropTarget::Tab(to) = target {
            self.move_item(drag.item_id, to);
        }
        if !creates_pane {
            cx.emit(PaneEvent::FocusRequested);
        }
        cx.notify();
    }

    /// Reorder an item to `to`, an insertion index in the current order.
    /// The active item follows the dragged tab.
    fn move_item(&mut self, item_id: u64, to: usize) {
        let Some(from) = self.items.iter().position(|item| item.id == item_id) else {
            return;
        };
        if to > self.items.len() || from == to || from + 1 == to {
            return;
        }
        let item = self.items.remove(from);
        let to = if from < to { to - 1 } else { to };
        self.items.insert(to, item);
        self.active_item = to;
        self.tab_scroll_handle.scroll_to_item(to);
    }

    /// Detach an item so another pane can adopt it. Caller persists layout.
    fn take_item(&mut self, item_id: u64) -> Option<TabTransfer> {
        let index = self.items.iter().position(|item| item.id == item_id)?;
        let item = self.items.remove(index);
        let editor = self.editors.remove(&item_id)?;
        self.result_subscriptions.remove(&item_id);
        let results = self.results.remove(&item_id);
        let clean_text = self.clean_documents.remove(&item_id).unwrap_or_default();
        let database_item_view = self.database_item_views.remove(&item_id);
        let database_query_text = self.database_query_texts.remove(&item_id);
        let database_ddl_text = self.database_ddl_texts.remove(&item_id);
        self.forget_item(item_id);
        self.active_item = self.active_item.min(self.items.len().saturating_sub(1));
        Some(TabTransfer {
            item,
            editor,
            results,
            clean_text,
            database_item_view,
            database_query_text,
            database_ddl_text,
        })
    }

    /// Adopt a tab detached from another pane at a requested tab-bar slot.
    fn receive_item(
        &mut self,
        transfer: TabTransfer,
        insertion_index: Option<usize>,
        cx: &mut Context<Self>,
    ) {
        let item_id = transfer.item.id;
        let editor = transfer.editor;
        self.editor_subscriptions.insert(
            item_id,
            cx.subscribe(&editor, move |pane, _, event, cx| {
                pane.on_editor_event(item_id, event, cx);
            }),
        );
        self.clean_documents.insert(item_id, transfer.clean_text);
        self.editors.insert(item_id, editor);
        if let Some(view) = transfer.database_item_view {
            self.database_item_views.insert(item_id, view);
        }
        if let Some(text) = transfer.database_query_text {
            self.database_query_texts.insert(item_id, text);
        }
        if let Some(text) = transfer.database_ddl_text {
            self.database_ddl_texts.insert(item_id, text);
        }
        if let Some(results) = transfer.results {
            self.attach_results(item_id, results, cx);
        }
        let insertion_index = insertion_index
            .unwrap_or(self.items.len())
            .min(self.items.len());
        self.items.insert(insertion_index, transfer.item);
        self.active_item = insertion_index;
        self.tab_scroll_handle.scroll_to_item(insertion_index);
        self.pending_close_item = None;
        cx.notify();
    }
}

impl Focusable for Pane {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl EventEmitter<PaneEvent> for Pane {}

fn pane_border_color(theme: &Theme, is_focused: bool) -> gpui::Hsla {
    if is_focused {
        theme.colors.accent
    } else {
        theme.colors.subtle_border
    }
}

fn pane_drop_preview_colors(theme: &Theme) -> (gpui::Hsla, gpui::Hsla) {
    let mut tint = theme.colors.muted_text;
    tint.a = 0.14;
    let mut border = theme.colors.muted_text;
    border.a = 0.62;
    (tint, border)
}

impl Pane {}

impl gpui::Render for Pane {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        let colors = theme.colors;
        let (pane_preview_tint, pane_preview_border) = pane_drop_preview_colors(&theme);
        let is_focused = self.active_focus_handle(cx).is_focused(window)
            || self.focus_handle.contains_focused(window, cx);
        let active = self.active_item().cloned();
        let has_tab_drag_preview =
            self.tab_drag_preview_bounds.is_some() && !self.suppress_tab_drag_preview;
        let database_notice = active.as_ref().and_then(|item| {
            if !matches!(item.source, Some(ItemSource::DatabaseObject(_))) {
                return None;
            }
            let state = self.database_item_states.get(&item.id)?.clone();
            (!matches!(state, DatabaseItemState::Live)).then_some((item.id, state))
        });
        let pending_close = active
            .as_ref()
            .filter(|item| self.pending_close_item == Some(item.id))
            .cloned();
        let has_items = !self.items.is_empty();
        let can_go_back = self.can_navigate_backward();
        let can_go_forward = self.can_navigate_forward();
        let item_count = self.items.len();
        let pane_id = self.id;
        div()
            .id(("pane", self.id as usize))
            .relative()
            .key_context("SiftPane")
            .track_focus(&self.focus_handle)
            // Clicking anywhere in the pane makes it the active pane. The
            // workspace owns the pane list, so we ask rather than reach across.
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|_, _, _, cx| cx.emit(PaneEvent::FocusRequested)),
            )
            .on_drag_move::<ResultResizeDrag>(cx.listener(Self::resize_results))
            .on_drop::<ResultResizeDrag>(cx.listener(Self::finish_results_resize))
            .flex()
            .flex_col()
            .flex_1()
            .min_w_0()
            .border_t_1()
            .border_color(pane_border_color(&theme, is_focused))
            .bg(colors.background)
            .children(has_items.then(|| {
                div()
                    .debug_selector(|| "pane-tab-bar".into())
                    .on_drag_move::<TabDrag>(cx.listener(Self::tab_bar_drag_hover))
                    .h(theme.metrics.tab_height)
                    .flex_none()
                    .flex()
                    .items_stretch()
                    .relative()
                    .bg(colors.toolbar)
                    .child(
                        div()
                            .w(EDITOR_GUTTER_WIDTH)
                            .h_full()
                            .flex_none()
                            .flex()
                            .items_center()
                            .border_r_1()
                            .border_color(colors.subtle_border)
                            .children(
                                [
                                    (
                                        "pane-go-back",
                                        IconName::ChevronLeft,
                                        "Go back",
                                        can_go_back,
                                        true,
                                    ),
                                    (
                                        "pane-go-forward",
                                        IconName::ChevronRight,
                                        "Go forward",
                                        can_go_forward,
                                        false,
                                    ),
                                ]
                                .into_iter()
                                .map(
                                    |(id, icon_name, label, enabled, backward)| {
                                        div()
                                            .id((id, pane_id as usize))
                                            .role(Role::Button)
                                            .aria_label(label)
                                            .w(EDITOR_GUTTER_WIDTH / 2.)
                                            .h_full()
                                            .flex_none()
                                            .flex()
                                            .items_center()
                                            .justify_center()
                                            .text_color(if enabled {
                                                colors.muted_text
                                            } else {
                                                colors.disabled_text
                                            })
                                            .when(enabled, |button| {
                                                button
                                                    .hover(|button| {
                                                        button
                                                            .bg(colors.hovered_surface)
                                                            .text_color(colors.text)
                                                    })
                                                    .on_click(cx.listener(
                                                        move |pane, _, window, cx| {
                                                            if backward {
                                                                pane.navigate_backward();
                                                            } else {
                                                                pane.navigate_forward();
                                                            }
                                                            pane.active_focus_handle(cx)
                                                                .focus(window, cx);
                                                            cx.emit(PaneEvent::FocusRequested);
                                                            cx.notify();
                                                        },
                                                    ))
                                            })
                                            .child(icon(
                                                icon_name,
                                                if enabled {
                                                    colors.muted_text
                                                } else {
                                                    colors.disabled_text
                                                },
                                                12.,
                                            ))
                                            .tooltip(move |_, cx| {
                                                cx.new(|_| Tooltip::new(label)).into()
                                            })
                                    },
                                ),
                            ),
                    )
                    .child(
                        div()
                            .absolute()
                            .left_0()
                            .right_0()
                            .bottom_0()
                            .h(px(1.))
                            .bg(colors.subtle_border),
                    )
                    .child(
                        div()
                            .relative()
                            .flex_1()
                            .min_w_0()
                            .h_full()
                            .overflow_x_hidden()
                            .child(
                                div()
                                    .id(("tabs-scroll", self.id as usize))
                                    .flex()
                                    .h_full()
                                    .overflow_x_scroll()
                                    .track_scroll(&self.tab_scroll_handle)
                                    .children(self.items.iter().enumerate().map(|(index, item)| {
                                        let selected = index == self.active_item;
                                        let item_id = item.id;
                                        let tab_debug = format!("tab-{item_id}");
                                        PaneTab::new(("tab", item.id as usize))
                                            .debug_selector(move || tab_debug.clone())
                                            .selected(selected)
                                            .dirty(item.dirty)
                                            .on_drag(
                                                TabDrag {
                                                    pane_id,
                                                    item_id,
                                                    index,
                                                    title: item.title.clone().into(),
                                                    selected,
                                                    dirty: item.dirty,
                                                },
                                                |tab, _, _, cx| cx.new(|_| tab.clone()),
                                            )
                                            .drag_over::<TabDrag>(move |tab, dragged, _, cx| {
                                                let mut tab = tab
                                                    .bg(cx.theme().colors.drop_target_background)
                                                    .border_color(
                                                        cx.theme().colors.drop_target_border,
                                                    )
                                                    .border_0();
                                                if dragged.pane_id != pane_id
                                                    || index < dragged.index
                                                {
                                                    tab = tab.border_l_2();
                                                } else if index > dragged.index {
                                                    tab = tab.border_r_2();
                                                }
                                                tab
                                            })
                                            .on_drop::<TabDrag>(cx.listener(
                                                move |pane, drag, window, cx| {
                                                    pane.finish_tab_bar_drag(
                                                        index, drag, window, cx,
                                                    )
                                                },
                                            ))
                                            .child(
                                                div()
                                                    .id(("tab-label", item.id as usize))
                                                    .flex()
                                                    .flex_1()
                                                    .min_w_0()
                                                    .items_center()
                                                    .h_full()
                                                    .pl_2()
                                                    .pr_1()
                                                    .hover(|label| label.text_color(colors.text))
                                                    .on_click(cx.listener(
                                                        move |pane, _, window, cx| {
                                                            pane.activate_item(index, true);
                                                            pane.active_focus_handle(cx)
                                                                .focus(window, cx);
                                                            cx.emit(PaneEvent::FocusRequested);
                                                            cx.notify();
                                                        },
                                                    ))
                                                    .child(
                                                        div()
                                                            .flex_1()
                                                            .min_w_0()
                                                            .truncate()
                                                            .when(
                                                                item.kind == ItemKind::Problems,
                                                                |label| {
                                                                    label
                                                                        .flex()
                                                                        .items_center()
                                                                        .gap_1()
                                                                        .child(icon(
                                                                            IconName::Warning,
                                                                            colors.warning,
                                                                            13.,
                                                                        ))
                                                                },
                                                            )
                                                            .child(item.title.clone()),
                                                    ),
                                            )
                                            .child(
                                                IconButton::new(
                                                    ("tab-close", item.id as usize),
                                                    IconName::Close,
                                                    format!("Close tab {}", item.title),
                                                )
                                                .square(px(22.))
                                                .icon_size(12.)
                                                .tooltip(format!("Close tab {}", item.title))
                                                .on_click(cx.listener(move |_, _, _, cx| {
                                                    cx.emit(PaneEvent::CloseItemRequested {
                                                        item_id,
                                                    });
                                                })),
                                            )
                                    }))
                                    .child(
                                        div()
                                            .id(("tab-bar-drop-target", pane_id as usize))
                                            .debug_selector(move || {
                                                format!("tab-bar-drop-target-{pane_id}")
                                            })
                                            .h_full()
                                            .min_w(px(24.))
                                            .flex_1()
                                            .child("")
                                            .drag_over::<TabDrag>(|target, _, _, cx| {
                                                target.bg(cx.theme().colors.drop_target_background)
                                            })
                                            .on_drop::<TabDrag>(cx.listener(
                                                move |pane, drag, window, cx| {
                                                    pane.finish_tab_bar_drag(
                                                        item_count, drag, window, cx,
                                                    )
                                                },
                                            )),
                                    ),
                            ),
                    )
            }))
            .children(pending_close.map(|item| {
                let item_id = item.id;
                let is_configuration = item.kind == ItemKind::Configuration;
                div()
                    .id(("dirty-close-strip", item_id as usize))
                    .h(theme.metrics.toolbar_height)
                    .flex_none()
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_3()
                    .border_b_1()
                    .border_color(colors.warning)
                    .bg(colors.warning_muted)
                    .text_sm()
                    .child(icon(IconName::Warning, colors.warning, 14.))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .child(format!("Discard changes to {}?", item.title)),
                    )
                    .child(
                        Button::new(("keep-editing", item_id as usize), "Keep editing")
                            .tone(ButtonTone::Ghost)
                            .on_click(cx.listener(move |pane, _, window, cx| {
                                pane.pending_close_item = None;
                                pane.active_focus_handle(cx).focus(window, cx);
                                cx.notify();
                            })),
                    )
                    .children(is_configuration.then(|| {
                        Button::new(("save-dirty-item", item_id as usize), "Save")
                            .tone(ButtonTone::Accent)
                            .on_click(cx.listener(move |_, _, _, cx| {
                                cx.emit(PaneEvent::SaveItemRequested { item_id });
                            }))
                    }))
                    .child(
                        Button::new(("discard-dirty-item", item_id as usize), "Discard")
                            .tone(ButtonTone::DangerGhost)
                            .on_click(cx.listener(move |_, _, _, cx| {
                                cx.emit(PaneEvent::DiscardItemRequested { item_id });
                            })),
                    )
            }))
            .child({
                let body = div()
                    .id(("pane-body", pane_id as usize))
                    .debug_selector(move || format!("pane-body-{pane_id}"))
                    .relative()
                    .flex_1()
                    .min_h_0()
                    .flex()
                    .flex_col()
                    .on_drag_move::<TabDrag>(cx.listener(Self::pane_drag_hover))
                    .on_drop::<TabDrag>(cx.listener(Self::finish_tab_drag));
                let body = match active {
                    Some(item) if item.kind == ItemKind::Configuration => {
                        match self.editors.get(&item.id) {
                            Some(editor) => {
                                body.child(div().flex_1().min_h_0().child(editor.clone()))
                            }
                            None => body.child(
                                div()
                                    .size_full()
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .text_color(colors.muted_text)
                                    .child("Configuration editor is unavailable"),
                            ),
                        }
                    }
                    Some(item)
                        if ItemRegistry::definition(&item.kind).runtime
                            == ItemRuntimeKind::ReadOnlyText =>
                    {
                        match self.editors.get(&item.id) {
                            Some(editor) => {
                                body.child(div().flex_1().min_h_0().child(editor.clone()))
                            }
                            None => body.child(
                                div()
                                    .size_full()
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .text_color(colors.muted_text)
                                    .child("Problems feed is unavailable"),
                            ),
                        }
                    }
                    Some(item)
                        if ItemRegistry::definition(&item.kind).runtime
                            == ItemRuntimeKind::Query =>
                    {
                        match (self.editors.get(&item.id), self.results.get(&item.id)) {
                            (Some(editor), Some(result)) => {
                                let database_view = self
                                    .database_item_views
                                    .get(&item.id)
                                    .copied()
                                    .unwrap_or(DatabaseItemView::Query);
                                let database_view_switch =
                                    self.database_ddl_texts.contains_key(&item.id).then(|| {
                                        let query_selected =
                                            database_view == DatabaseItemView::Query;
                                        let item_id = item.id;
                                        div()
                                            .h(px(28.))
                                            .flex_none()
                                            .flex()
                                            .items_center()
                                            .gap_1()
                                            .px_2()
                                            .border_b_1()
                                            .border_color(colors.subtle_border)
                                            .bg(colors.toolbar)
                                            .child(
                                                Button::new(
                                                    ("database-query-view", item_id as usize),
                                                    "Query",
                                                )
                                                .tone(if query_selected {
                                                    ButtonTone::Neutral
                                                } else {
                                                    ButtonTone::Ghost
                                                })
                                                .on_click(cx.listener(move |pane, _, _, cx| {
                                                    pane.show_database_item_view(
                                                        item_id,
                                                        DatabaseItemView::Query,
                                                        None,
                                                        cx,
                                                    );
                                                })),
                                            )
                                            .child(
                                                Button::new(
                                                    ("database-ddl-view", item_id as usize),
                                                    "DDL",
                                                )
                                                .tone(if query_selected {
                                                    ButtonTone::Ghost
                                                } else {
                                                    ButtonTone::Neutral
                                                })
                                                .on_click(cx.listener(move |pane, _, _, cx| {
                                                    pane.show_database_item_view(
                                                        item_id,
                                                        DatabaseItemView::Ddl,
                                                        None,
                                                        cx,
                                                    );
                                                })),
                                            )
                                    });
                                let placement = result.read(cx).placement();
                                let extent = self
                                    .live_result_extents
                                    .get(&item.id)
                                    .copied()
                                    .unwrap_or_else(|| result.read(cx).extent());
                                let item_id = item.id;
                                let resize_hitbox = div()
                                    .id(("resize-query-results", item_id as usize))
                                    .debug_selector(move || {
                                        format!("resize-query-results-{item_id}")
                                    })
                                    .absolute()
                                    .flex_none()
                                    .cursor(match placement {
                                        ResultPlacement::Bottom => CursorStyle::ResizeUpDown,
                                        ResultPlacement::Right => CursorStyle::ResizeLeftRight,
                                    })
                                    .block_mouse_except_scroll()
                                    .when(placement == ResultPlacement::Bottom, |handle| {
                                        handle
                                            .left_0()
                                            .top(px(-(RESULT_RESIZE_HANDLE_SIZE - 1.0) / 2.0))
                                            .w_full()
                                            .h(px(RESULT_RESIZE_HANDLE_SIZE))
                                    })
                                    .when(placement == ResultPlacement::Right, |handle| {
                                        handle
                                            .top_0()
                                            .left(px(-(RESULT_RESIZE_HANDLE_SIZE - 1.0) / 2.0))
                                            .h_full()
                                            .w(px(RESULT_RESIZE_HANDLE_SIZE))
                                    })
                                    .on_drag(
                                        ResultResizeDrag { item_id, placement },
                                        |_, _, _, cx| cx.new(|_| gpui::Empty),
                                    )
                                    .tooltip(move |_, cx| {
                                        cx.new(|_| Tooltip::new("Drag to resize results")).into()
                                    });
                                let handle = div()
                                    .id(("query-results-separator", item_id as usize))
                                    .debug_selector(move || {
                                        format!("query-results-separator-{item_id}")
                                    })
                                    .relative()
                                    .flex_none()
                                    .bg(colors.subtle_border)
                                    .when(placement == ResultPlacement::Bottom, |handle| {
                                        handle.w_full().h(px(1.0))
                                    })
                                    .when(placement == ResultPlacement::Right, |handle| {
                                        handle.h_full().w(px(1.0))
                                    })
                                    .child(resize_hitbox);
                                let split = if self.expanded_result_item == Some(item_id) {
                                    div()
                                        .size_full()
                                        .min_h_0()
                                        .min_w_0()
                                        .child(editor.clone())
                                        .into_any_element()
                                } else {
                                    match placement {
                                        ResultPlacement::Bottom => div()
                                            .size_full()
                                            .min_h_0()
                                            .flex()
                                            .flex_col()
                                            .child(div().flex_1().min_h_0().child(editor.clone()))
                                            .child(handle)
                                            .child(
                                                div()
                                                    .h(px(extent))
                                                    .flex_none()
                                                    .flex()
                                                    .min_h_0()
                                                    .child(result.clone()),
                                            )
                                            .into_any_element(),
                                        ResultPlacement::Right => div()
                                            .size_full()
                                            .min_w_0()
                                            .flex()
                                            .child(div().flex_1().min_w_0().child(editor.clone()))
                                            .child(handle)
                                            .child(
                                                div()
                                                    .w(px(extent))
                                                    .flex_none()
                                                    .flex()
                                                    .min_w_0()
                                                    .child(result.clone()),
                                            )
                                            .into_any_element(),
                                    }
                                };
                                body.children(database_view_switch).child(split)
                            }
                            _ => body.child(
                                div()
                                    .size_full()
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .p_4()
                                    .text_color(colors.muted_text)
                                    .child(format!("Query editor · {}", item.title)),
                            ),
                        }
                    }
                    Some(item) => {
                        let definition = ItemRegistry::definition(&item.kind);
                        let message = definition.placeholder_prefix.map_or_else(
                            || definition.empty_message.to_owned(),
                            |prefix| format!("{prefix} · {}", item.title),
                        );
                        body.child(
                            div()
                                .size_full()
                                .flex()
                                .items_center()
                                .justify_center()
                                .p_4()
                                .child(
                                    div()
                                        .max_w(px(420.))
                                        .min_w_0()
                                        .text_center()
                                        .text_color(colors.muted_text)
                                        .whitespace_normal()
                                        .child(message),
                                ),
                        )
                    }
                    None => body.child(
                        div()
                            .size_full()
                            .flex()
                            .items_center()
                            .justify_center()
                            .p_4()
                            .text_center()
                            .text_color(colors.muted_text)
                            .child("No open items"),
                    ),
                };
                let target = self.tab_drop_target.unwrap_or(PaneDropTarget::Center);
                body.children(has_tab_drag_preview.then(|| {
                    div()
                        .debug_selector(move || match target {
                            PaneDropTarget::Center => "pane-drop-preview-center".into(),
                            PaneDropTarget::Above => "pane-drop-preview-above".into(),
                            PaneDropTarget::Before => "pane-drop-preview-before".into(),
                            PaneDropTarget::After => "pane-drop-preview-after".into(),
                            PaneDropTarget::Below => "pane-drop-preview-below".into(),
                            PaneDropTarget::Tab(_) => unreachable!(),
                        })
                        .absolute()
                        .bg(pane_preview_tint)
                        .border_2()
                        .border_color(pane_preview_border)
                        .when(target == PaneDropTarget::Center, |preview| {
                            preview.inset_0()
                        })
                        .when(target == PaneDropTarget::Before, |preview| {
                            preview
                                .left_0()
                                .top_0()
                                .bottom_0()
                                .w(DefiniteLength::Fraction(0.5))
                        })
                        .when(target == PaneDropTarget::After, |preview| {
                            preview
                                .right_0()
                                .top_0()
                                .bottom_0()
                                .w(DefiniteLength::Fraction(0.5))
                        })
                        .when(target == PaneDropTarget::Above, |preview| {
                            preview
                                .left_0()
                                .right_0()
                                .top_0()
                                .h(DefiniteLength::Fraction(0.5))
                        })
                        .when(target == PaneDropTarget::Below, |preview| {
                            preview
                                .left_0()
                                .right_0()
                                .bottom_0()
                                .h(DefiniteLength::Fraction(0.5))
                        })
                }))
            })
            .children(database_notice.map(|(item_id, state)| {
                let (tint, can_retry) = match state {
                    DatabaseItemState::Live => unreachable!(),
                    DatabaseItemState::Offline => (colors.warning_muted, true),
                    DatabaseItemState::Reconnecting => (colors.warning_muted, false),
                    DatabaseItemState::Failed(_) => (colors.danger_muted, true),
                };
                div()
                    .id(("database-snapshot-overlay", item_id as usize))
                    .debug_selector(|| "database-snapshot-overlay".into())
                    .absolute()
                    .left_0()
                    .right_0()
                    .top(theme.metrics.tab_height)
                    .bottom_0()
                    .bg(tint)
                    .when(can_retry, |overlay| {
                        overlay
                            .cursor(CursorStyle::OperationNotAllowed)
                            .on_click(cx.listener(move |_, _, _, cx| {
                                cx.emit(PaneEvent::RefreshDatabaseItemRequested { item_id });
                            }))
                    })
            }))
    }
}

/// One streamed page held back from its tab, with the acknowledgement that
/// resumes the server stream. Dropping this cancels the query, which is the
/// correct outcome when its tab goes away.
struct HeldResultPage {
    execution_id: u64,
    cursor_id: sift_protocol::CursorId,
    page: sift_protocol::Page,
    acknowledge: tokio::sync::oneshot::Sender<()>,
}

fn targeted_query_text(document: &QueryDocument) -> String {
    let selected = document.selected_text().trim();
    if !selected.is_empty() {
        return selected.to_owned();
    }
    document
        .active_statement()
        .map(|range| document.text()[range].trim().to_owned())
        .filter(|sql| !sql.is_empty())
        .unwrap_or_else(|| document.text().trim().to_owned())
}

/// Wall-clock milliseconds, used only to stamp result references. A clock that
/// cannot be read yields 0, which reads as "unknown" rather than failing a run.
fn epoch_millis() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_millis() as u64)
}

/// Find positional placeholders outside SQL strings and comments. Both
/// PostgreSQL (`$1`) and SQL Server (`@p1`) spellings map to the same ordered
/// parameter vector used by the protocol.
fn detect_query_parameters(sql: &str) -> Vec<String> {
    #[derive(Clone, Copy)]
    enum ScanState {
        Sql,
        SingleQuote,
        DoubleQuote,
        LineComment,
        BlockComment,
    }

    let bytes = sql.as_bytes();
    let mut state = ScanState::Sql;
    let mut index = 0;
    let mut max_parameter = 0;
    let mut sql_server_style = false;
    while index < bytes.len() {
        match state {
            ScanState::Sql if bytes[index..].starts_with(b"--") => {
                state = ScanState::LineComment;
                index += 2;
            }
            ScanState::Sql if bytes[index..].starts_with(b"/*") => {
                state = ScanState::BlockComment;
                index += 2;
            }
            ScanState::Sql if bytes[index] == b'\'' => {
                state = ScanState::SingleQuote;
                index += 1;
            }
            ScanState::Sql if bytes[index] == b'"' => {
                state = ScanState::DoubleQuote;
                index += 1;
            }
            ScanState::Sql if bytes[index] == b'$' => {
                if let Some(delimiter_end) = postgres_dollar_quote_delimiter(bytes, index) {
                    let delimiter = &sql[index..delimiter_end];
                    let body_start = delimiter_end;
                    index = sql[body_start..]
                        .find(delimiter)
                        .map_or(bytes.len(), |offset| body_start + offset + delimiter.len());
                    continue;
                }
                let start = index + 1;
                let mut end = start;
                while end < bytes.len() && bytes[end].is_ascii_digit() {
                    end += 1;
                }
                if end > start {
                    if let Ok(value) = sql[start..end].parse::<usize>() {
                        max_parameter = max_parameter.max(value);
                    }
                    index = end;
                } else {
                    index += 1;
                }
            }
            ScanState::Sql
                if bytes[index] == b'@'
                    && index + 2 < bytes.len()
                    && matches!(bytes[index + 1], b'p' | b'P')
                    && bytes[index + 2].is_ascii_digit() =>
            {
                let start = index + 2;
                let mut end = start;
                while end < bytes.len() && bytes[end].is_ascii_digit() {
                    end += 1;
                }
                if let Ok(value) = sql[start..end].parse::<usize>() {
                    max_parameter = max_parameter.max(value);
                    sql_server_style = true;
                }
                index = end;
            }
            ScanState::Sql => index += 1,
            ScanState::SingleQuote if bytes[index] == b'\'' => {
                if bytes.get(index + 1) == Some(&b'\'') {
                    index += 2;
                } else {
                    state = ScanState::Sql;
                    index += 1;
                }
            }
            ScanState::DoubleQuote if bytes[index] == b'"' => {
                if bytes.get(index + 1) == Some(&b'"') {
                    index += 2;
                } else {
                    state = ScanState::Sql;
                    index += 1;
                }
            }
            ScanState::LineComment if bytes[index] == b'\n' => {
                state = ScanState::Sql;
                index += 1;
            }
            ScanState::BlockComment if bytes[index..].starts_with(b"*/") => {
                state = ScanState::Sql;
                index += 2;
            }
            ScanState::SingleQuote
            | ScanState::DoubleQuote
            | ScanState::LineComment
            | ScanState::BlockComment => index += 1,
        }
    }

    (1..=max_parameter)
        .map(|number| {
            if sql_server_style {
                format!("@p{number}")
            } else {
                format!("${number}")
            }
        })
        .collect()
}

fn postgres_dollar_quote_delimiter(bytes: &[u8], start: usize) -> Option<usize> {
    let first = *bytes.get(start + 1)?;
    if first == b'$' {
        return Some(start + 2);
    }
    if !(first.is_ascii_alphabetic() || first == b'_') {
        return None;
    }
    let mut index = start + 2;
    while bytes
        .get(index)
        .is_some_and(|byte| byte.is_ascii_alphanumeric() || *byte == b'_')
    {
        index += 1;
    }
    (bytes.get(index) == Some(&b'$')).then_some(index + 1)
}

fn parameter_binding_key(sql: &str) -> String {
    use sha2::{Digest as _, Sha256};

    let normalized = sql.split_whitespace().collect::<Vec<_>>().join(" ");
    format!("{:x}", Sha256::digest(normalized.as_bytes()))
}

fn parse_parameter_value(text: &str) -> Result<sift_protocol::Value, String> {
    let trimmed = text.trim();
    if trimmed.eq_ignore_ascii_case("null") {
        return Ok(sift_protocol::Value::Null);
    }
    if trimmed.is_empty() {
        return Ok(sift_protocol::Value::Text(String::new()));
    }
    let looks_typed = matches!(trimmed.as_bytes().first(), Some(b'"' | b'[' | b'{'))
        || matches!(trimmed, "true" | "false")
        || trimmed.parse::<i64>().is_ok()
        || trimmed.parse::<f64>().is_ok();
    if !looks_typed {
        return Ok(sift_protocol::Value::Text(trimmed.to_owned()));
    }
    let value: serde_json::Value = serde_json::from_str(trimmed)
        .map_err(|error| format!("Expected text or a valid JSON value: {error}"))?;
    Ok(match value {
        serde_json::Value::Null => sift_protocol::Value::Null,
        serde_json::Value::Bool(value) => sift_protocol::Value::Bool(value),
        serde_json::Value::Number(value) => value.as_i64().map_or_else(
            || sift_protocol::Value::Decimal(value.to_string()),
            sift_protocol::Value::Int64,
        ),
        serde_json::Value::String(value) => sift_protocol::Value::Text(value),
        value @ (serde_json::Value::Array(_) | serde_json::Value::Object(_)) => {
            sift_protocol::Value::Json(value)
        }
    })
}

#[derive(Debug, Clone)]
pub struct ResultEditApplyFailure {
    pub message: String,
    pub conflict: Option<sift_protocol::EditConflict>,
}

fn staged_result_row_index(edits: &[StagedResultEdit], edit_index: usize) -> usize {
    let Some(target) = edits.get(edit_index) else {
        return 0;
    };
    let mut rows: Vec<&[(String, sift_protocol::Value)]> = Vec::new();
    for edit in edits.iter().take(edit_index + 1) {
        if !rows.contains(&edit.original_row.as_slice()) {
            rows.push(&edit.original_row);
        }
        if edit.original_row == target.original_row {
            return rows.len().saturating_sub(1);
        }
    }
    0
}

/// One coalescing window for keystroke-driven reanalysis. Long enough that a
/// fast typist produces one request per pause, short enough that diagnostics
/// feel attached to the edit that caused them.
const SEMANTIC_ANALYZE_DEBOUNCE: std::time::Duration = std::time::Duration::from_millis(160);

