    fn table_graph() -> sift_protocol::CatalogGraph {
        use sift_protocol::{
            CatalogCompleteness, CatalogCoverage, CatalogGraphData, CatalogNode,
            CatalogNodeDetails, CatalogNodeKind, CatalogObjectId, CatalogRevision, ColumnMetadata,
            DialectId, PrimitiveType, ProviderId, ProviderRef, TypeRef,
        };
        use std::collections::BTreeMap;
        let catalog_id = CatalogObjectId("catalog".into());
        let schema_id = CatalogObjectId("schema".into());
        let table_id = CatalogObjectId("table".into());
        let node = |id: CatalogObjectId,
                    kind: CatalogNodeKind,
                    name: &str,
                    qualified_name: &str,
                    parent_id: Option<CatalogObjectId>,
                    ordinal: Option<u32>,
                    details: CatalogNodeDetails| CatalogNode {
            id,
            native_id: None,
            kind,
            name: name.into(),
            qualified_name: qualified_name.into(),
            parent_id,
            ordinal,
            definition_digest: None,
            completeness: CatalogCompleteness::Complete,
            details,
            extra: BTreeMap::new(),
        };
        sift_protocol::CatalogGraph {
            revision: CatalogRevision(7),
            content_digest: "catfp:test".into(),
            invalidation_epoch: 1,
            captured_at: serde_json::from_value(serde_json::json!("2026-01-01T00:00:00Z")).unwrap(),
            provider: ProviderRef {
                provider_id: ProviderId::new("sift/postgres").unwrap(),
                dialect_id: DialectId::new("sift/postgres").unwrap(),
                provider_version: "1".into(),
            },
            database_identity: "sifttest".into(),
            data: CatalogGraphData {
                coverage: CatalogCoverage::complete(),
                nodes: vec![
                    node(
                        catalog_id.clone(),
                        CatalogNodeKind::Catalog,
                        "sifttest",
                        "sifttest",
                        None,
                        None,
                        CatalogNodeDetails::None,
                    ),
                    node(
                        schema_id.clone(),
                        CatalogNodeKind::Schema,
                        "lab",
                        "sifttest.lab",
                        Some(catalog_id),
                        None,
                        CatalogNodeDetails::None,
                    ),
                    node(
                        table_id.clone(),
                        CatalogNodeKind::Table,
                        "people",
                        "sifttest.lab.people",
                        Some(schema_id),
                        None,
                        CatalogNodeDetails::Object { routine_args: None },
                    ),
                    node(
                        CatalogObjectId("column-id".into()),
                        CatalogNodeKind::Column,
                        "id",
                        "sifttest.lab.people.id",
                        Some(table_id),
                        Some(1),
                        CatalogNodeDetails::Column {
                            column: ColumnMetadata::new(
                                "id",
                                TypeRef::Primitive(PrimitiveType::Int64),
                            ),
                        },
                    ),
                    node(
                        CatalogObjectId("column-name".into()),
                        CatalogNodeKind::Column,
                        "name",
                        "sifttest.lab.people.name",
                        Some(CatalogObjectId("table".into())),
                        Some(2),
                        CatalogNodeDetails::Column {
                            column: {
                                let mut column = ColumnMetadata::new(
                                    "name",
                                    TypeRef::Primitive(PrimitiveType::Text),
                                );
                                column.nullable = sift_protocol::Nullability::Nullable;
                                column
                            },
                        },
                    ),
                ],
                edges: Vec::new(),
            },
        }
    }

    fn table_graph_with_details() -> sift_protocol::CatalogGraph {
        use sift_protocol::{
            CatalogCompleteness, CatalogNode, CatalogNodeDetails, CatalogNodeKind, CatalogObjectId,
            ConstraintInfo, ConstraintKind, IndexInfo, IndexKind, TriggerEvent, TriggerInfo,
            TriggerTiming,
        };
        use std::collections::BTreeMap;

        let mut graph = table_graph();
        let detail_node = |id: &str,
                           kind: CatalogNodeKind,
                           name: &str,
                           details: CatalogNodeDetails| CatalogNode {
            id: CatalogObjectId(id.into()),
            native_id: None,
            kind,
            name: name.into(),
            qualified_name: format!("sifttest.lab.people.{name}"),
            parent_id: Some(CatalogObjectId("table".into())),
            ordinal: None,
            definition_digest: None,
            completeness: CatalogCompleteness::Complete,
            details,
            extra: BTreeMap::new(),
        };
        graph.data.nodes.extend([
            detail_node(
                "index-name",
                CatalogNodeKind::Index,
                "people_name_idx",
                CatalogNodeDetails::Index {
                    index: IndexInfo {
                        name: "people_name_idx".into(),
                        columns: vec!["name".into()],
                        unique: false,
                        primary_key: false,
                        kind: IndexKind::Btree,
                        partial_predicate: Some("name IS NOT NULL".into()),
                    },
                },
            ),
            detail_node(
                "relation-team",
                CatalogNodeKind::Constraint,
                "people_team_fk",
                CatalogNodeDetails::Constraint {
                    constraint: ConstraintInfo {
                        name: "people_team_fk".into(),
                        kind: ConstraintKind::ForeignKey,
                        columns: vec!["team_id".into()],
                        definition: Some("FOREIGN KEY (team_id) REFERENCES lab.teams(id)".into()),
                        references: Some("lab.teams".into()),
                    },
                },
            ),
            detail_node(
                "trigger-touch",
                CatalogNodeKind::Trigger,
                "people_touch",
                CatalogNodeDetails::Trigger {
                    trigger: TriggerInfo {
                        name: "people_touch".into(),
                        timing: TriggerTiming::Before,
                        events: vec![TriggerEvent::Update],
                        columns: vec![],
                        definition: Some(
                            "CREATE TRIGGER people_touch BEFORE UPDATE ON lab.people;".into(),
                        ),
                    },
                },
            ),
        ]);
        graph
    }

    fn shell(cx: &mut TestAppContext) -> gpui::WindowHandle<WorkspaceShell> {
        cx.update(|cx| {
            cx.open_window(Default::default(), |window, cx| {
                cx.new(|cx| {
                    WorkspaceShell::new(
                        Default::default(),
                        Default::default(),
                        None,
                        None,
                        window,
                        cx,
                    )
                })
            })
            .unwrap()
        })
    }

    fn shell_with_state(
        state: PresentationState,
        cx: &mut TestAppContext,
    ) -> gpui::WindowHandle<WorkspaceShell> {
        cx.update(|cx| {
            cx.open_window(Default::default(), |window, cx| {
                cx.new(|cx| WorkspaceShell::new(state, Default::default(), None, None, window, cx))
            })
            .unwrap()
        })
    }

    #[test]
    fn edge_resize_handles_are_disabled_when_window_fills_the_screen() {
        assert!(edge_resize_enabled(false, false));
        assert!(!edge_resize_enabled(true, false));
        assert!(!edge_resize_enabled(false, true));
        assert!(!edge_resize_enabled(true, true));
    }

    #[gpui::test]
    fn server_switch_swaps_and_restores_full_workspace_session(cx: &mut TestAppContext) {
        let mut state = PresentationState::default();
        state.workspace.workspace_id = Some(11);
        let mut remote = PresentationState::default().workspace;
        remote.instance_id = Some("hosted:team".into());
        remote.workspace_id = Some(22);
        remote.panes[0].items[0].kind = ItemKind::Welcome;
        remote.panes[0].items[0].title = "Team home".into();
        state
            .instance_workspaces
            .insert("hosted:team".into(), remote);

        let window = shell_with_state(state, cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.executor_sender = Some(sender);
            let editor = shell.panes[0].read(cx).editor(1).unwrap().clone();
            editor.update(cx, |editor, cx| {
                editor.replace_text_in_range(None, "select 'local'", window, cx)
            });
            shell.switch_instance_workspace("hosted:team", window, cx);
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::Disconnect)
        ));
        workspace.read_with(&cx, |shell, cx| {
            assert_eq!(shell.selected_workspace_id, Some(22));
            assert_eq!(shell.panes[0].read(cx).items[0].title, "Team home");
        });

        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.switch_instance_workspace("local", window, cx)
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::Disconnect)
        ));
        workspace.read_with(&cx, |shell, cx| {
            assert_eq!(shell.selected_workspace_id, Some(11));
            assert_eq!(
                shell.panes[0]
                    .read(cx)
                    .editor(1)
                    .unwrap()
                    .read(cx)
                    .document()
                    .text(),
                "select 'local'"
            );
            let snapshot = shell.snapshot(cx);
            assert_eq!(
                snapshot.instance_workspaces["hosted:team"].workspace_id,
                Some(22)
            );
        });
    }

