    #[gpui::test]
    fn saved_queries_panel_routes_crud_and_reopens_sql(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();
        let saved = sift_api_types::SavedQuery {
            id: sift_api_types::SavedQueryId(7),
            tenant_id: sift_api_types::TenantId(1),
            owner_principal_id: Some(sift_api_types::PrincipalId(1)),
            name: "Recent events".into(),
            sql_text: "select * from lab.audit_events".into(),
            connection_profile_id: Some(sift_api_types::ConnectionProfileId(2)),
            tags: Vec::new(),
            created_at: "2026-08-24T10:00:00Z".parse().unwrap(),
            updated_at: "2026-08-24T10:00:00Z".parse().unwrap(),
            revision: 3,
        };

        workspace.update(&mut cx, |shell, cx| {
            shell.executor_sender = Some(sender);
            shell.lifecycle.tenants = vec![crate::TenantNavEntry {
                id: sift_api_types::TenantId(1),
                name: "demo".into(),
                rooms: Vec::new(),
                connections: Vec::new(),
            }];
            shell.select_left_panel(LeftPanel::SavedQueries, cx);
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::LoadSavedQueries { tenant_id: 1 })
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.on_executor_event(
                ExecutorEvent::SavedQueriesLoaded {
                    tenant_id: 1,
                    result: Ok(vec![saved.clone()]),
                },
                cx,
            )
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("saved-queries-scroll").is_some());

        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.open_saved_query(saved.clone(), window, cx)
        });
        workspace.read_with(&cx, |shell, cx| {
            let pane = shell.panes[shell.active_pane].read(cx);
            let item = pane.active_item().unwrap();
            assert_eq!(item.title, "Recent events.sql");
            assert_eq!(
                pane.editor(item.id).unwrap().read(cx).document().text(),
                saved.sql_text
            );
        });

        workspace.update(&mut cx, |shell, cx| shell.save_active_query(cx));
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::CreateSavedQuery { request })
                if request.name == "Recent events" && request.sql_text == saved.sql_text
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.update_saved_query_from_active(saved.id, saved.revision, cx)
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::UpdateSavedQuery { id, request })
                if id == saved.id && request.sql_text.as_deref() == Some(saved.sql_text.as_str())
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.begin_rename_saved_query(saved.id, saved.name.clone(), cx);
            shell
                .saved_query_name_input
                .update(cx, |input, cx| input.set_text("Audit trail", cx));
            shell.finish_rename_saved_query(saved.id, saved.revision, cx);
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::UpdateSavedQuery { id, request })
                if id == saved.id && request.name.as_deref() == Some("Audit trail")
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.delete_saved_query(saved.id, saved.revision, cx)
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::DeleteSavedQuery { id, expected_revision: 3 })
                if id == saved.id
        ));
    }

    #[gpui::test]
    fn footer_transaction_controls_track_begin_commit_and_rollback(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();
        let transaction = sift_protocol::TransactionInfo {
            tx_id: sift_protocol::TxId::new(9),
            connection: sift_protocol::ConnectionId(2),
            mode: sift_protocol::TxMode::default(),
            opened_at: "2026-08-24T10:00:00Z".parse().unwrap(),
        };
        workspace.update(&mut cx, |shell, cx| {
            shell.executor_sender = Some(sender);
            shell.on_executor_event(
                ExecutorEvent::Connection(ConnectionStatus::Connected {
                    profile_id: 2,
                    name: "demo/postgres".into(),
                }),
                cx,
            );
        });
        cx.run_until_parked();

        assert!(cx.debug_bounds("footer-begin-transaction").is_none());
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.run_command(CommandId::BeginTransaction, window, cx)
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::BeginTransaction)
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.on_executor_event(
                ExecutorEvent::TransactionChanged(Ok(Some(transaction.clone()))),
                cx,
            )
        });
        cx.run_until_parked();
        assert_eq!(
            workspace.read_with(&cx, |shell, _| shell.status.transaction.clone()),
            "TX: 9"
        );

        let commit = cx.debug_bounds("footer-commit-transaction").unwrap();
        cx.simulate_click(commit.center(), Modifiers::default());
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::CommitTransaction)
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.on_executor_event(ExecutorEvent::TransactionChanged(Ok(None)), cx)
        });
        cx.run_until_parked();

        assert!(cx.debug_bounds("footer-begin-transaction").is_none());
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.run_command(CommandId::BeginTransaction, window, cx)
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::BeginTransaction)
        ));
        workspace.update(&mut cx, |shell, cx| {
            shell.on_executor_event(ExecutorEvent::TransactionChanged(Ok(Some(transaction))), cx)
        });
        cx.run_until_parked();
        let rollback = cx.debug_bounds("footer-rollback-transaction").unwrap();
        cx.simulate_click(rollback.center(), Modifiers::default());
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::RollbackTransaction)
        ));
    }

    #[gpui::test]
    fn transaction_blocks_ambiguous_commits_and_warns_before_disconnect(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();
        let transaction = sift_protocol::TransactionInfo {
            tx_id: sift_protocol::TxId::new(11),
            connection: sift_protocol::ConnectionId(2),
            mode: sift_protocol::TxMode::default(),
            opened_at: "2026-08-24T10:00:00Z".parse().unwrap(),
        };

        workspace.update(&mut cx, |shell, cx| {
            shell.executor_sender = Some(sender);
            shell.transaction = Some(transaction);
            shell.running_queries.insert(1, 9);
            shell.finish_transaction(true, cx);
            assert!(receiver.try_recv().is_err());
            shell.running_queries.clear();
            shell.on_executor_event(
                ExecutorEvent::TransactionStateRefreshed(Ok(Some(
                    sift_protocol::TransactionState {
                        transaction: shell.transaction.clone().unwrap(),
                        savepoints: Vec::new(),
                        condition: sift_protocol::TransactionCondition::Failed,
                    },
                ))),
                cx,
            );
            assert!(shell.transaction_aborted);
            assert_eq!(shell.status.transaction, "TX: Failed");
            shell.finish_transaction(true, cx);
            assert!(receiver.try_recv().is_err());
            shell.finish_transaction(false, cx);
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::RollbackTransaction)
        ));

        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.transaction_pending = false;
            shell.disconnect(cx);
            assert_eq!(shell.modal, Some(Modal::ConfirmTransactionDisconnect));
            assert!(receiver.try_recv().is_err());
            shell.confirm_transaction_disconnect(window, cx);
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::Disconnect)
        ));
        assert!(workspace.read_with(&cx, |shell, _| shell.transaction.is_none()));
    }

    #[gpui::test]
    fn connection_health_tracks_latency_failure_layer_and_reconnects(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.executor_sender = Some(sender);
            shell.connection_status = ConnectionStatus::Connected {
                profile_id: 2,
                name: "demo/postgres".into(),
            };
            shell.open_table_preview(
                DatabaseObjectTarget {
                    connection: ConnectionNavEntry {
                        id: 2,
                        tenant_id: 1,
                        name: "demo/postgres".into(),
                        provider_id: sift_protocol::ProviderId::new("sift/postgres").unwrap(),
                    },
                    catalog: "sifttest".into(),
                    schema: "audit".into(),
                    object: "events".into(),
                    object_kind: sift_protocol::ObjectKind::Table,
                },
                window,
                cx,
            );
            shell.on_executor_event(
                ExecutorEvent::ConnectionHealth(ConnectionHealthReport {
                    checked_at_ms: 1_000,
                    latency_ms: 7,
                    failure: None,
                }),
                cx,
            );
            assert_eq!(shell.connection_last_success_ms, Some(1_000));
            shell.on_executor_event(
                ExecutorEvent::ConnectionHealth(ConnectionHealthReport {
                    checked_at_ms: 2_000,
                    latency_ms: 31,
                    failure: Some(ConnectionHealthFailure::Database(
                        "connection refused".into(),
                    )),
                }),
                cx,
            );
            assert_eq!(shell.connection_last_success_ms, Some(1_000));
        });
        while receiver.try_recv().is_ok() {}
        cx.run_until_parked();
        assert!(matches!(
            workspace.read_with(&cx, |shell, _| shell
                .connection_health
                .as_ref()
                .and_then(|report| report.failure.as_ref())
                .cloned()),
            Some(ConnectionHealthFailure::Database(message)) if message == "connection refused"
        ));
        workspace.update(&mut cx, |shell, cx| shell.reconnect(cx));
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::Connect {
                tenant_id: 1,
                profile_id: 2,
                name,
            }) if name == "demo/postgres"
        ));
    }

